mapper.update:
UPDATE sys_tenant_access_publish_task
SET status = 'SUPERSEDED', updated_at_ms = #{nowMs}
WHERE tenant_id = #{tenantId} AND status = 'PENDING'

UPDATE sys_tenant_access_publish_task
SET status = 'PROCESSING', active_lease_key = #{tenantId}, lease_owner = #{owner},
    lease_until_ms = #{leaseUntilMs}, updated_at_ms = #{nowMs}
WHERE id = #{id} AND tenant_id = #{tenantId}
  AND ((status = 'PENDING' AND next_attempt_at_ms <= #{nowMs})
    OR (status = 'PROCESSING' AND lease_until_ms < #{nowMs}))

UPDATE sys_tenant_access_publish_task
SET status = 'PUBLISHED', active_lease_key = NULL, lease_owner = NULL, lease_until_ms = 0,
    last_error = NULL, published_at_ms = #{nowMs}, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}

UPDATE sys_tenant_access_publish_task
SET status = #{status}, attempts = #{attempts}, next_attempt_at_ms = #{nextAttemptAtMs},
    active_lease_key = NULL, lease_owner = NULL, lease_until_ms = 0,
    last_error = #{error}, updated_at_ms = #{nowMs}
WHERE id = #{id} AND status = 'PROCESSING' AND lease_owner = #{owner}
